    ,('AI Futures Fellowship', NULL, 'Instituto Tecnológico Autónomo de México', 'https://aifuturesfellowship.org/', 'https://aifuturesfellowship.org/team', 'aifuturesfellowship@gmail.com', 'Mexico', '2023-07-17', 'year', 'https://aifuturesfellowship.org/', 'https://aifuturesfellowship.org/ https://aifuturesfellowship.org/team https://aifuturesfellowship.org/team-1 https://aifuturesfellowship.org/more-faqs', 'AI Futures Fellowship was an eight-week, full-time fellowship based at the Instituto Tecnológico Autónomo de México in Mexico City. It supported early-career researchers working on catastrophic and existential risks from advanced AI, including AI governance and technical AI safety. Its first cohort ran from January 8 to March 1, 2024. The website states that there was no application round for 2025.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL)
    ,('AI & Partners', NULL, NULL, 'https://www.ai-and-partners.com/', 'https://www.ai-and-partners.com/about-us', 'contact@ai-and-partners.com', 'Netherlands', '2021-01-01', 'year', 'https://www.linkedin.com/company/ai-%26-partners/about/', 'https://www.ai-and-partners.com/ https://www.ai-and-partners.com/about-us https://www.linkedin.com/company/ai-%26-partners/ https://x.com/AI_and_Partners', 'AI & Partners is a privately held AI governance and regulatory-compliance company headquartered in Amsterdam. It provides software, consulting, assessments, auditing preparation, and training to help organizations manage AI risks and comply with requirements such as the European Union AI Act and ISO/IEC 42001.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'AI_and_Partners', NULL, NULL)
