    ,('AI Security Institute', 'AI Safety Institute; AISI', 'Department for Science, Innovation and Technology', 'https://www.aisi.gov.uk/', 'https://www.aisi.gov.uk/about', NULL, 'United Kingdom', '2023-11-02', 'day', 'https://www.gov.uk/government/news/prime-minister-launches-new-ai-safety-institute', 'https://www.aisi.gov.uk/ https://www.aisi.gov.uk/about https://www.gov.uk/government/news/prime-minister-launches-new-ai-safety-institute https://www.linkedin.com/company/ai-security-institute/ https://x.com/AISecurityInst/ https://en.wikipedia.org/wiki/AI_Security_Institute', 'The AI Security Institute (AISI) is a UK government research organization within the Department for Science, Innovation and Technology. It conducts research and evaluations to understand the capabilities and risks of advanced AI and to develop and test mitigations. It evolved from the Frontier AI Taskforce and launched as the AI Safety Institute on November 2, 2023. It was renamed the AI Security Institute on February 14, 2025.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'AISecurityInst', 'https://en.wikipedia.org/wiki/AI_Security_Institute', NULL)
