    ,('Animal Defense Partnership', 'ADP', NULL, 'https://www.animaldefensepartnership.org/', 'https://www.animaldefensepartnership.org/mission', 'info@animaldefensepartnership.org', 'United States', '2016-01-01', 'year', 'https://www.animaldefensepartnership.org/mission', 'https://www.animaldefensepartnership.org/ https://www.animaldefensepartnership.org/mission https://www.animaldefensepartnership.org/contact', 'Animal Defense Partnership (ADP) provides free legal services to nonprofits advocating for animals and plant-based diets. Its services include legal counsel, governance and compliance support, contracts, fundraising agreements, intellectual property guidance, conflict resolution, and educational resources. Since its founding in 2016, ADP has provided millions of dollars in pro bono legal services to hundreds of organizations, strengthening the legal infrastructure of the animal protection movement.', NULL, NULL, 'animaldefensepartnership', NULL, NULL, NULL, NULL, NULL, NULL, NULL)
    ,('Animal Welfare Institute', 'AWI', NULL, 'https://awionline.org/', 'https://awionline.org/about-us/our-team/', 'awi@awionline.org', 'United States', '1951-07-10', 'day', 'https://awionline.org/about-us/awi-celebrating-75-years/awi-and-history-of-animal-welfare/', 'https://awionline.org/ https://awionline.org/about-us/ https://awionline.org/about-us/our-team/ https://awionline.org/about-us/contact-us/ https://www.facebook.com/animalwelfareinstitute/ https://www.instagram.com/awionline/ https://www.linkedin.com/company/animal-welfare-institute/ https://x.com/AWIOnline', 'Animal Welfare Institute (AWI) is a US nonprofit animal-protection organization founded by Christine Stevens. It works to alleviate animal suffering caused by people and improve the treatment of animals in agriculture, commerce, homes and communities, research, and the wild. Its programs cover animals in laboratories, companion animals, equines, farmed animals, marine wildlife, and terrestrial wildlife.', NULL, 'animalwelfareinstitute', 'awionline', NULL, NULL, NULL, NULL, 'AWIOnline', NULL, NULL)
    ,('Anima International', NULL, NULL, 'https://animainternational.org/', 'https://animainternational.org/about/team', 'contact@animainternational.org', 'Poland', '2018-01-01', 'year', 'https://animainternational.org/about/history', 'https://animainternational.org/ https://animainternational.org/about/history https://animainternational.org/about/team https://x.com/anima_int https://www.linkedin.com/company/anima-international/', 'Anima International is a multinational animal advocacy organization focused on reducing animal suffering, particularly in industrial farming. It conducts investigations, corporate and policy campaigns, and movement-building activities, while promoting plant-based diets. Formed in 2018 through the merger of Anima (Scandinavia) and Open Cages (Poland), it operates across multiple European countries and coordinates international advocacy efforts.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '@anima_int', NULL, NULL)
