    ,('Berggruen Institute', 'BI', NULL, 'https://berggruen.org/', 'https://berggruen.org/people', 'institute@berggruen.org', 'United States', '2010-01-01', 'year', 'https://berggruen.org/about', 'https://berggruen.org/ https://berggruen.org/about https://berggruen.org/people https://berggruen.org/contact https://www.linkedin.com/company/berggrueninst/ https://www.facebook.com/berggrueninst/ https://www.instagram.com/berggrueninst/ https://x.com/berggruenInst https://www.youtube.com/@Berggrueninst https://en.wikipedia.org/wiki/Berggruen_Institute', 'Berggruen Institute is an independent, nonpartisan think tank founded by Nicolas Berggruen and Nathan Gardels. It develops ideas concerning governance, economics, geopolitics, philosophy, culture, science, and technology. Headquartered in Los Angeles, it also operates centers in Beijing and Venice and publishes Noema Magazine.', NULL, 'berggrueninst', 'berggrueninst', NULL, NULL, NULL, NULL, 'berggruenInst', 'https://en.wikipedia.org/wiki/Berggruen_Institute', '@Berggrueninst')
    ,('Berkeley Artificial Intelligence Research', 'BAIR; Berkeley Artificial Intelligence Research Lab', 'University of California, Berkeley', 'https://bair.berkeley.edu/', 'https://bair.berkeley.edu/people/staff', 'bair-website@berkeley.edu', 'United States', '2016-01-01', 'year', 'https://eecs.berkeley.edu/news/bair-lab-forms-research-partnership-chinas-huawei-noahs-ark-lab/', 'https://bair.berkeley.edu/ https://bair.berkeley.edu/about https://bair.berkeley.edu/people/faculty https://bair.berkeley.edu/people/staff https://bair.berkeley.edu/people/students https://www.facebook.com/BAIRLab/ https://x.com/berkeley_ai https://www.linkedin.com/company/bair-lab/', 'Berkeley Artificial Intelligence Research (BAIR) is an academic research laboratory at the University of California, Berkeley. It brings together faculty, graduate students, postdoctoral researchers, and staff working in computer vision, machine learning, natural language processing, planning, control, robotics, human-compatible AI, and responsible AI.', NULL, 'BAIRLab', NULL, NULL, NULL, NULL, NULL, 'berkeley_ai', NULL, NULL)
