    ,('Blue Horizon', 'Blue Horizon Corporation AG', NULL, 'https://bluehorizon.com/', NULL, 'info@bluehorizon.com', 'Switzerland', '2016-01-01', 'year', 'https://bluehorizon.com/', 'https://bluehorizon.com/ https://bluehorizon.com/contact/', 'Blue Horizon is a Switzerland-based investment firm focused on accelerating the transition to a sustainable food system. It backs companies at the intersection of biology, technology, and agriculture, particularly in alternative proteins and food innovation. Its “Double Positive” philosophy seeks to generate both above-market financial returns and measurable positive impact for the planet, humans, and animals. The firm supports startups and platforms through capital investment, ecosystem building, and strategic growth initiatives.', '2026-04-27', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL)
    ,('Cambridge Boston Alignment Initiative', 'CBAI', NULL, 'https://www.cbai.ai/', 'https://www.cbai.ai/', 'contact@cbai.ai', 'United States', '2022-01-01', 'year', 'https://www.cbai.ai/', 'https://www.cbai.ai/ https://www.cbai.ai/contact-us https://www.linkedin.com/company/cbalignment/ https://x.com/cbai_ai', 'Cambridge Boston Alignment Initiative (CBAI) is a Cambridge, Massachusetts-based 501(c)(3) public charity. It conducts and supports research and educational programs intended to help society navigate a safe and beneficial transition to advanced AI systems. Its programs include AI safety and AI-biosecurity research fellowships and CAMBRIA.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'cbai_ai', NULL, NULL)
