    ,('Connect For Animals', 'CFA', NULL, 'https://connectforanimals.com/', 'https://connectforanimals.com/about', NULL, 'United States', '2022-01-01', 'month', 'https://connectforanimals.com/about', 'https://connectforanimals.com/ https://connectforanimals.com/about https://connectforanimals.com/contact https://connectforanimals.com/events https://www.linkedin.com/company/connectforanimals/ https://www.facebook.com/connectforanimals/ https://www.instagram.com/connectforanimals/', 'Connect For Animals (CFA) is a nonprofit platform that connects people with events, organizations, resources, and opportunities to take action against factory farming. Founded by Steven Rouk in Colorado, it expanded across the United States and became a registered 501(c)(3) public charity in 2023. It is registered in New York under EIN 93-1805772.', NULL, 'connectforanimals', 'connectforanimals', NULL, NULL, NULL, NULL, NULL, NULL, NULL)
    ,('Consultants for Impact', 'CFI', 'Rethink Priorities', 'https://www.consultantsforimpact.org/', 'https://www.consultantsforimpact.org/network-directory#meet', NULL, NULL, NULL, NULL, NULL, 'https://www.consultantsforimpact.org/ https://www.consultantsforimpact.org/network-directory#meet https://www.facebook.com/consultantsforimpact/ https://www.instagram.com/consultantsforimpact/ https://www.linkedin.com/company/consultants-for-impact/', 'Consultants for Impact (CFI) is a global network of consultants focused on maximizing their positive impact. It provides career support, community, and resources to help current and former consultants transition into high-impact roles across areas such as global health, AI safety, and climate. The project is fiscally sponsored by Rethink Priorities and emphasizes evidence-based career decision-making and community building.', NULL, 'consultantsforimpact', 'consultantsforimpact', NULL, NULL, NULL, NULL, NULL, NULL, NULL)
