    ,('ControlAI', 'Control AI', NULL, 'https://controlai.org/', 'https://controlai.org/about', 'hello@controlai.com', 'United Kingdom', '2023-10-01', 'month', 'https://en.wikipedia.org/wiki/ControlAI', 'https://controlai.org/ https://controlai.com/ https://controlai.news/ https://campaign.controlai.com/ https://www.linkedin.com/company/controlai/ https://discord.com/invite/ptPScqtdc5 https://x.com/ControlAI https://www.facebook.com/people/Control-AI/61552397246469/ https://www.instagram.com/ai_ctrl/ https://www.youtube.com/@ControlAI https://www.tiktok.com/@ctrl.ai https://www.threads.com/@ai_ctrl https://bsky.app/profile/controlai.com https://en.wikipedia.org/wiki/ControlAI', 'ControlAI is a London-based nonprofit advocacy organization working to prevent existential risk from artificial superintelligence and keep humanity in control of advanced AI development. It advocates prohibiting the development of superintelligent AI while supporting narrower beneficial AI applications. Andrea Miotti founded the organization and serves as its CEO.', NULL, NULL, 'ai_ctrl', NULL, NULL, NULL, NULL, 'ControlAI', 'ControlAI', 'ControlAI')
    ,('Convergence Analysis', NULL, NULL, 'https://www.convergenceanalysis.org/', 'https://www.convergenceanalysis.org/team', 'contact@convergenceanalysis.org', 'United States', '2017-01-01', 'year', 'https://www.convergenceanalysis.org/about-us', 'https://www.convergenceanalysis.org/ https://www.convergenceanalysis.org/about-us https://www.convergenceanalysis.org/team https://www.convergenceanalysis.org/contact-us https://www.convergenceanalysis.org/blog/announcing-convergence-analysis-ai-scenario-governance-research https://www.linkedin.com/company/convergence-analysis', 'Convergence Analysis is an independent nonprofit research organization studying transformative-AI scenarios and governance interventions intended to mitigate existential and societal risks from AI. It originated in 2017 as an existential-risk strategy research collaboration between David Kristoffersson and Justin Shovelain, was legally formed as a California nonprofit in 2018, and publicly relaunched as an expanded AI scenario and governance research institute in March 2024. EIN: 83-2842233.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL)
